struct HostCallBuilder {
  typedef HostCall Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_OP(::flatbuffers::Offset<::flatbuffers::String> OP) {
    fbb_.AddOffset(HostCall::VT_OP, OP);
  }
  void add_PARAMS_type(sdn::runtime::HostCallParams PARAMS_type) {
    fbb_.AddElement<uint8_t>(HostCall::VT_PARAMS_TYPE, static_cast<uint8_t>(PARAMS_type), 0);
  }
  void add_PARAMS(::flatbuffers::Offset<void> PARAMS) {
    fbb_.AddOffset(HostCall::VT_PARAMS, PARAMS);
  }
  explicit HostCallBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<HostCall> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<HostCall>(end);
    fbb_.Required(o, HostCall::VT_OP);
    return o;
  }
};

inline ::flatbuffers::Offset<HostCall> CreateHostCall(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> OP = 0,
    sdn::runtime::HostCallParams PARAMS_type = sdn::runtime::HostCallParams_NONE,
    ::flatbuffers::Offset<void> PARAMS = 0) {
  HostCallBuilder builder_(_fbb);
  builder_.add_PARAMS(PARAMS);
  builder_.add_OP(OP);
  builder_.add_PARAMS_type(PARAMS_type);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<HostCall> CreateHostCallDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const char *OP = nullptr,
    sdn::runtime::HostCallParams PARAMS_type = sdn::runtime::HostCallParams_NONE,
    ::flatbuffers::Offset<void> PARAMS = 0) {
  auto OP__ = OP ? _fbb.CreateString(OP) : 0;
  return sdn::runtime::CreateHostCall(
      _fbb,
      OP__,
      PARAMS_type,
      PARAMS);
}

::flatbuffers::Offset<HostCall> CreateHostCall(::flatbuffers::FlatBufferBuilder &_fbb, const HostCallT *_o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);

inline HostCallT *HostCall::UnPack(const ::flatbuffers::resolver_function_t *_resolver) const {
  auto _o = std::unique_ptr<HostCallT>(new HostCallT());
  UnPackTo(_o.get(), _resolver);
  return _o.release();
}

inline void HostCall::UnPackTo(HostCallT *_o, const ::flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = OP(); if (_e) _o->OP = _e->str(); }
  { auto _e = PARAMS_type(); _o->PARAMS.type = _e; }
  { auto _e = PARAMS(); if (_e) _o->PARAMS.value = sdn::runtime::HostCallParamsUnion::UnPack(_e, PARAMS_type(), _resolver); }
}

inline ::flatbuffers::Offset<HostCall> CreateHostCall(::flatbuffers::FlatBufferBuilder &_fbb, const HostCallT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return HostCall::Pack(_fbb, _o, _rehasher);
}

inline ::flatbuffers::Offset<HostCall> HostCall::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const HostCallT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const HostCallT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _OP = _fbb.CreateString(_o->OP);
  auto _PARAMS_type = _o->PARAMS.type;
  auto _PARAMS = _o->PARAMS.Pack(_fbb);
  return sdn::runtime::CreateHostCall(
      _fbb,
      _OP,
      _PARAMS_type,
      _PARAMS);
}

