template <bool B>
inline bool VerifyHostCallParamsVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyHostCallParams(
        verifier,  values->Get(i), types->GetEnum<HostCallParams>(i))) {
      return false;
    }
  }
  return true;
}

