inline const sdn::runtime::HostCall *GetHostCall(const void *buf) {
  return ::flatbuffers::GetRoot<sdn::runtime::HostCall>(buf);
}

inline const sdn::runtime::HostCall *GetSizePrefixedHostCall(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<sdn::runtime::HostCall>(buf);
}

inline const char *HostCallIdentifier() {
  return "HCLQ";
}

inline bool HostCallBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, HostCallIdentifier());
}

inline bool SizePrefixedHostCallBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, HostCallIdentifier(), true);
}

template <bool B = false>
inline bool VerifyHostCallBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<sdn::runtime::HostCall>(HostCallIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedHostCallBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<sdn::runtime::HostCall>(HostCallIdentifier());
}

inline void FinishHostCallBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<sdn::runtime::HostCall> root) {
  fbb.Finish(root, HostCallIdentifier());
}

inline void FinishSizePrefixedHostCallBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<sdn::runtime::HostCall> root) {
  fbb.FinishSizePrefixed(root, HostCallIdentifier());
}

inline std::unique_ptr<sdn::runtime::HostCallT> UnPackHostCall(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<sdn::runtime::HostCallT>(GetHostCall(buf)->UnPack(res));
}

inline std::unique_ptr<sdn::runtime::HostCallT> UnPackSizePrefixedHostCall(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<sdn::runtime::HostCallT>(GetSizePrefixedHostCall(buf)->UnPack(res));
}

